export async function cropDetectedBoxes(platform,canvas,boxes,options){let toolkit=platform.canvas.getToolkit();let crops=[];for(const[index,box]of boxes.entries()){let cropCanvas=toolkit.crop({bbox:{x0:box.x,y0:box.y,x1:box.x+box.width,y1:box.y+box.height},canvas});if(options.saveCropsTo&&platform.saveImage){let filename=`crop_${String(index).padStart(3,"0")}.png`;await platform.saveImage(cropCanvas,[options.saveCropsTo,filename].join(platform.pathSeparator))}if(options.crop){crops.push(await canvasToPngBuffer(cropCanvas))}}return crops}async function canvasToPngBuffer(canvas){let c=canvas;if(typeof c.toBuffer==="function"){let buffer=c.toBuffer("image/png");return buffer.buffer.slice(buffer.byteOffset,buffer.byteOffset+buffer.byteLength)}if(typeof c.convertToBlob==="function"){let blob=await c.convertToBlob({type:"image/png"});return blob.arrayBuffer()}if(typeof c.toBlob==="function"){let toBlob=c.toBlob.bind(c);let blob=await new Promise((resolve,reject)=>toBlob((b)=>b?resolve(b):reject(new Error("Canvas toBlob() returned null")),"image/png"));return blob.arrayBuffer()}throw new Error("Canvas cannot be encoded to a PNG buffer on this platform")}